const authSlice = createSlice({ name: "auth", initialState: { token: localStorage.getItem("token"), user: JSON.parse(localStorage.getItem("user") || "null") as User | null }, reducers: {
  setAuth: (state, action: PayloadAction<{ token: string; user: User; refresh?: string }>) => { state.token = action.payload.token; state.user = action.payload.user; localStorage.setItem("token", action.payload.token); localStorage.setItem("user", JSON.stringify(action.payload.user)); if (action.payload.refresh) localStorage.setItem("refresh_token", action.payload.refresh); },
  clear: state => { state.token = null; state.user = null; localStorage.removeItem("token"); localStorage.removeItem("user"); localStorage.removeItem("refresh_token"); },
}});
const store = configureStore({ reducer: { auth: authSlice.reducer } });
type RootState = ReturnType<typeof store.getState>;
const refreshAccessToken = async () => {
  const refresh = localStorage.getItem("refresh_token");
  if (!refresh) return null;
  const response = await fetch(`${API}/auth/refresh/`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ refresh }) });
  if (!response.ok) return null;
  const data = await response.json();
  localStorage.setItem("token", data.access);
  return data.access as string;
};
const client = async (path: string, token: string, options: RequestInit = {}, retry = true) => {
  const response = await fetch(`${API}${path}`, { ...options, headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...(options.headers || {}) } });
  if (response.status === 401 && retry) {
    const refreshed = await refreshAccessToken();
    if (refreshed) return client(path, refreshed, options, false);
  }
  if (!response.ok) {
    const body = await response.json().catch(() => ({}));
    const error = new Error(body.detail || "Request failed");
    if (response.status === 401) error.name = "UnauthorizedError";
    throw error;
  }
  return response.json();
};
