  const details: Record<string, { title: string; body: string; actions: string[] }> = {
    projects: { title: "Project command", body: `You can review all ${projectCount.toLocaleString()} capital projects across every authorized entity. Use the action controls in the project register below to advance or reject requests.`, actions: ["View all projects", "Create project", "Export project register"] },
    budgets: { title: "Budget command", body: "You can monitor portfolio allocations, actual spend, variance, and category-level financial performance from the controls below.", actions: ["Review allocations", "Export budget report", "Inspect variance"] },
    approvals: { title: "Approval command", body: `${pending.toLocaleString()} requests currently require attention. The The Lead Admin can approve, reject, and advance workflow actions across every entity.`, actions: ["Review pending", "Audit approval history", "Export approvals"] },
    administration: { title: "Lead Admin administration", body: "You have full authority to manage entities, users, roles, property access, confidential profits, and platform governance.", actions: ["Add entity", "Manage every user", "Manage permissions"] },
  };
